import{_ as o,c as r,o as a,a2 as e}from"./chunks/framework.CHomSxuB.js";const q=JSON.parse('{"title":"3 · 方法论沉淀","description":"","frontmatter":{},"headers":[],"relativePath":"足球信号雷达/3-方法论沉淀.md","filePath":"足球信号雷达/3-方法论沉淀.md"}'),l={name:"足球信号雷达/3-方法论沉淀.md"};function n(s,t,i,d,u,h){return a(),r("div",null,t[0]||(t[0]=[e('<h1 id="_3-·-方法论沉淀" tabindex="-1">3 · 方法论沉淀 <a class="header-anchor" href="#_3-·-方法论沉淀" aria-label="Permalink to &quot;3 · 方法论沉淀&quot;">​</a></h1><blockquote><p>这一篇不写&quot;哪个信号赚钱&quot;，写<strong>算赔率账时最容易算错的地方</strong>——全是踩坑换来的、跨场景可复用的方法学。 状态：已沉淀（2026-08~09 实践确立），后续新线直接引用。</p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p><hr><h2 id="一、均值陷阱-e-f-赔率-f-e-赔率" tabindex="-1">一、均值陷阱：<code>E[f(赔率)] ≠ f(E[赔率])</code> <a class="header-anchor" href="#一、均值陷阱-e-f-赔率-f-e-赔率" aria-label="Permalink to &quot;一、均值陷阱：`E[f(赔率)] ≠ f(E[赔率])`&quot;">​</a></h2><p>赔率复合函数是非线性凹函数，<strong>用&quot;平均赔率&quot;推期望，系统性地高估收益</strong>。</p><ul><li>实证：某信号用平均赔率测算 +11.9% 收益，<strong>逐场实结算只有 +0.3%</strong>——差了近 40 倍。</li></ul><p><strong>纪律：一切策略验证必须逐场结算，严禁赔率均值估算。</strong>（这条后来也支撑了 A 股侧&quot;预注册 + 只跑一次&quot;的协议精神。）</p><h2 id="二、亚盘水位-→-概率方法学-2026-09-02-实践确立" tabindex="-1">二、亚盘水位 → 概率方法学（2026-09-02 实践确立） <a class="header-anchor" href="#二、亚盘水位-→-概率方法学-2026-09-02-实践确立" aria-label="Permalink to &quot;二、亚盘水位 → 概率方法学（2026-09-02 实践确立）&quot;">​</a></h2><p>目标：把亚盘水位转换成与欧赔同构的隐含概率，两套视角互相校验。</p><p>四个坑与修法（每一步都有真实翻车案例）：</p><ol><li><strong>水位是&quot;净赢倍率&quot;，先 +1 才是总赔率</strong>：<code>总赔率 = 1 + 水位</code>，隐含概率 = <code>1 / (1 + 水位)</code>，再按 Σ 去抽水。 直接拿水位取倒数会算飞。</li><li><strong>走盘/赢半必须排除出命中率分母</strong>：平半盘的平局、半一盘的净胜 1 球都属走盘/赢半。 不排除会校准失真——初版因此把真实主赢盘率误判虚高到 64%，修正后回到 ~48%。</li><li><strong>背离必须同口径对比</strong>：直接算「亚盘主赢盘概率 − 欧赔主胜概率」是错误指标——让球本身就会造成 5~10pp 差异。 只比对语义等价事件：主让半球≡主胜 / 主受让半球≡主不败 / 平半盘借平赔拆分。</li><li><strong>检验转化质量看&quot;校准&quot;，不看&quot;方向命中率&quot;</strong>：亚盘经让球平衡后方向本就 ≈50%，命中率 ≈50% 是正常设计，不是信号失效。</li></ol><p>顺带结论：<strong>亚盘抽水通常 2~6%，远低于欧赔 8~12%</strong>（单日实测 5.2% vs 8.6%）——亚盘视角更&quot;干净&quot;， 是校验欧赔信号质量的好镜子。单日 52 场中 35 场有亚盘缓存，14 场可同口径对照中有 7 场背离 ≥5pp → 有挖掘价值（尚未成规则）。</p><h2 id="三、校准-vs-命中率-两种-准-不是一回事" tabindex="-1">三、校准 vs 命中率：两种&quot;准&quot;不是一回事 <a class="header-anchor" href="#三、校准-vs-命中率-两种-准-不是一回事" aria-label="Permalink to &quot;三、校准 vs 命中率：两种&quot;准&quot;不是一回事&quot;">​</a></h2><ul><li><strong>方向命中率</strong>回答&quot;信号方向对不对&quot;——但市场方向本来就是有偏的（热门方向天然命中高）；</li><li><strong>校准</strong>回答&quot;隐含概率与真实发生频率是否一致&quot;——这才是判断&quot;赔率有没有被错误定价&quot;的正确标尺。</li></ul><p>A 股侧对应物：超额收益要对标基准指数（中证 1000），而不是看绝对涨跌——<strong>脱离基准谈命中都是自嗨</strong>。</p><h2 id="四、欧亚同向性观测-候选过滤-未转正" tabindex="-1">四、欧亚同向性观测（候选过滤，未转正） <a class="header-anchor" href="#四、欧亚同向性观测-候选过滤-未转正" aria-label="Permalink to &quot;四、欧亚同向性观测（候选过滤，未转正）&quot;">​</a></h2><p>&quot;亚盘让球受益方 = 欧赔信号受益方&quot;记同向，反之为冲突：</p><table tabindex="0"><thead><tr><th>口径</th><th>同向命中</th><th>反向（冲突）命中</th><th>差值</th></tr></thead><tbody><tr><td>回测验证</td><td>83.0%</td><td>62.3%</td><td>+20.7pp</td></tr><tr><td>OOS 跟踪（截至 09-02）</td><td>83.3%（n=1064）</td><td>62.7%（n=177）</td><td>+20.6pp</td></tr></tbody></table><p>解读（区分证据与叙事）：</p><ul><li><strong>证据</strong>：同向场次命中显著高于冲突场次，OOS 与回测几乎重合（+20.6 vs +20.7pp），这一条目前是全场最稳的统计结构；</li><li><strong>叙事（推测）</strong>：方向冲突 = 市场自己没想明白，信号可信度随之下降。</li><li><strong>处置</strong>：仅观测，未改任何信号；若维持可成候选过滤规则（规则化必须走预注册，禁止直接并入现役信号）。</li></ul><h2 id="五、可复用的纪律清单-跨-a-股-足球通用" tabindex="-1">五、可复用的纪律清单（跨 A 股 / 足球通用） <a class="header-anchor" href="#五、可复用的纪律清单-跨-a-股-足球通用" aria-label="Permalink to &quot;五、可复用的纪律清单（跨 A 股 / 足球通用）&quot;">​</a></h2><ol><li>结论必须带 <strong>n（样本）与口径与日期</strong>；样本不足只描述不裁决；</li><li>区分 <strong>证据（实测）</strong> 与 <strong>叙事（机理推测）</strong>，叙事不作结论引用；</li><li>同一段历史挖参数 = 过拟合；规则冻结后不再调阈值；</li><li>验证看 <strong>OOS / 逐场实结算 / 校准</strong>，不看回测均值、不看方向命中率、不看&quot;看着很赚&quot;的叙事；</li><li>扣除真实摩擦（A 股双边佣金印花、足球抽水）之后再谈 edge。</li></ol><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p>',24)]))}const g=o(l,[["render",n]]);export{q as __pageData,g as default};
